{"path":"assets/css/styles.css","content":"/* Reset and base */
:root{
  --bg:#fbfdfc;
  --muted:#6b7280;
  --accent1:#7BE495;
  --accent2:#5CA6FF;
  --accent3:#FFD38C;
  --text:#0f172a;
  --card:#ffffff;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--text);background:linear-gradient(180deg,var(--bg),#f7fbff);}
.wrap{max-width:1100px;margin:0 auto;padding:0 20px}
a{color:inherit;text-decoration:none}
.small{font-size:0.9rem}
.muted{color:var(--muted)}

/* Header */
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;background:transparent;position:sticky;top:0;z-index:50}
.brand{display:flex;align-items:center}
.logo{display:flex;gap:12px;align-items:center}
.brand-name{font-weight:700}
.nav{position:relative}
.nav-toggle{display:none;background:none;border:1px solid var(--muted);padding:8px 10px;border-radius:8px}
.nav-list{list-style:none;display:flex;gap:16px;margin:0;padding:0}
.nav-list a{padding:8px 6px;border-radius:6px}
.btn{display:inline-block;padding:10px 16px;border-radius:8px;border:0;background:var(--accent2);color:white;font-weight:600}
.btn.ghost{background:transparent;border:1px solid rgba(15,23,42,0.06);color:var(--text)}
.btn.slim{padding:8px 12px}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2))}
.btn.primary.large{padding:14px 20px;font-size:1.05rem}
.primary-ghost{background:transparent;border:1px solid rgba(15,23,42,0.06);padding:8px 10px;border-radius:8px}

/* Hero split diagonal */
.hero.split{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center;padding:48px 20px;position:relative}
.hero-left{max-width:620px}
.eyebrow{color:var(--accent2);font-weight:700;margin:0}
.headline{font-size:2.2rem;margin:10px 0}
.sub{color:var(--muted);margin-bottom:18px}
.hero-right{position:relative}
.diagonal-card{position:relative;border-radius:16px;overflow:hidden;box-shadow:0 10px 30px rgba(12,15,27,0.06);transform:skewX(-6deg);}
.diagonal-card .card-copy{transform:skewX(6deg);padding:28px;background:linear-gradient(180deg,rgba(255,255,250,0.9),rgba(240,255,255,0.9));}
.diagonal-card .list-check{margin:12px 0 16px;padding-left:18px}
.list-check li{margin-bottom:6px}

/* Sections */
.section{padding:36px 20px}
.section.light{background:linear-gradient(180deg,#ffffff, #fbfeff);border-top:1px solid rgba(10,15,20,0.02)}
.section-title{font-size:1.4rem;margin:0 0 8px}
.lead{color:var(--muted);margin:0 0 18px}
.card-grid .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(12,15,27,0.04)}

/* Pillars */
.pillars{display:flex;gap:16px;padding-top:12px}
.pillar{background:linear-gradient(180deg,rgba(255,255,255,0.7),rgba(250,252,255,0.7));padding:18px;border-radius:12px;flex:1;text-align:center}
.icon{width:48px;height:48px;margin:0 auto 8px;display:block}

/* Case notes */
.notes{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.note{background:linear-gradient(180deg,#fff,#fbfefe);padding:14px;border-radius:10px}
.disclaimer{margin-top:12px}

/* FAQ */
.qa details{background:#fff;padding:12px;border-radius:10px;margin-bottom:8px}
.qa summary{cursor:pointer;font-weight:600}

/* Cta split */
.split-cta{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:center;padding:28px;background:linear-gradient(90deg,#f6fffb,#fff9f7);border-radius:14px}
.cta-left h3{margin:0 0 8px}
.trust{background:transparent}

/* Footer */
.site-footer{padding:20px;border-top:1px solid rgba(12,15,27,0.04);margin-top:28px}
.fnav{display:flex;gap:12px}

/* Responsive */
@media (max-width:980px){
  .hero.split{grid-template-columns:1fr;}
  .hero-right{order:2}
  .nav-list{display:none;position:absolute;right:0;top:48px;background:white;padding:12px;border-radius:8px;box-shadow:0 12px 40px rgba(12,15,27,0.08)}
  .nav-toggle{display:inline-block}
  .nav-list.open{display:flex;flex-direction:column;gap:8px}
  .card-grid .grid{grid-template-columns:1fr}
  .notes{grid-template-columns:1fr}
  .pillars{flex-direction:column}
  .split-cta{grid-template-columns:1fr}
}

/* Pattern overlay using svg file */
.hero-right .pattern{opacity:0.95;width:100%;height:100%;display:block}

/* small helpers */
.small{font-size:0.85rem}
.eyebrow{font-size:0.95rem}
.headline{line-height:1.05}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Small UI helpers: nav toggle, year injection, smooth scroll
  var navToggle = document.getElementById('nav-toggle');
  var navList = document.getElementById('nav-list');
  if(navToggle){
    navToggle.addEventListener('click',function(){
      var open = navList.classList.toggle('open');
      navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }

  // Year
  var y = new Date().getFullYear();
  var yearEl = document.getElementById('year');
  if(yearEl) yearEl.textContent = y;

  // Smooth scroll for same-page anchors
  document.addEventListener('click', function(e){
    var a = e.target.closest('a');
    if(!a) return;
    var href = a.getAttribute('href');
    if(href && href.indexOf('#')===0){
      e.preventDefault();
      var id = href.slice(1);
      var el = document.getElementById(id);
      if(el){
        el.scrollIntoView({behavior:'smooth',block:'start'});
      }
    }
  });

  // Replace phone/email placeholders in any dynamic contexts (if present)
  function replacePlaceholders(){
    var phoneEls = document.querySelectorAll('[href^="tel:"]');
    phoneEls.forEach(function(el){
      var h = el.getAttribute('href');
      if(h && h.indexOf('{{PHONE}}')>-1){
        el.setAttribute('href', 'tel:{{PHONE}}');
      }
    });
    var mailEls = document.querySelectorAll('[href^="mailto:"]');
    mailEls.forEach(function(el){
      var h = el.getAttribute('href');
      if(h && h.indexOf('{{EMAIL}}')>-1){
        el.setAttribute('href', 'mailto:{{EMAIL}}');
      }
    });
  }
  replacePlaceholders();
})();"} 
